#!/usr/bin/env python3
"""Compute standard v1 ground truth for CSX-297_Q1."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path


TASK_ID = "CSX-297_Q1"
EVENT_ID = "CSX-297"
PACKAGE_RELATIVE_PATH = "event_packages/standard_event_packages/packages/CSX-297"


def load_json(package_dir: Path, relative_path: str) -> dict:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(package_dir: Path, relative_path: str) -> str:
    with (package_dir / relative_path).open("r", encoding="utf-8", errors="ignore") as handle:
        return handle.read()


def strip_html(raw_html: str) -> str:
    text = re.sub(r"<script\b.*?</script>", " ", raw_html, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def longest_run(values: list[float], threshold: float) -> int:
    best = 0
    current = 0
    for value in values:
        if value <= threshold:
            current += 1
        else:
            current = 0
        best = max(best, current)
    return best


def count_terms(text: str, terms: list[str]) -> dict[str, int]:
    return {
        term: len(re.findall(re.escape(term), text, flags=re.IGNORECASE))
        for term in terms
    }


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / PACKAGE_RELATIVE_PATH

    source_paths = {
        "report": "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
        "anchor": "data/event_reports/event_reports_003_Locked_event_anchor_2019_Indonesian_haze_and_smoke.json",
        "power": "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json",
        "open_meteo": "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json",
        "population": "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json",
        "amenities": "data/exposure_impact/exposure_impact_001_Overpass_small_roads_and_critical_amenities.json",
        "embedding_change": "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    }

    report_text = strip_html(read_text(package_dir, source_paths["report"]))
    anchor = load_json(package_dir, source_paths["anchor"])
    power = load_json(package_dir, source_paths["power"])
    open_meteo = load_json(package_dir, source_paths["open_meteo"])
    population = load_json(package_dir, source_paths["population"])
    amenities = load_json(package_dir, source_paths["amenities"])
    embedding_change = load_json(package_dir, source_paths["embedding_change"])

    power_precip_by_day = power["properties"]["parameter"]["PRECTOTCORR"]
    power_precip = [float(value) for value in power_precip_by_day.values()]
    daily = open_meteo["daily"]
    point_precip = [float(value) for value in daily["precipitation_sum"]]
    point_wind = [float(value) for value in daily["wind_speed_10m_max"]]

    dry_run_days = longest_run(power_precip, 0.0)
    point_precip_total_mm = round(sum(point_precip), 1)
    peak_wind_kmh = round(max(point_wind), 1)
    exposed_population_rounded = round(float(population["population_sum"]["population"]))
    alphaearth_change_mean = round(
        float(embedding_change["stats"]["alphaearth_1_minus_cosine_mean"]), 4
    )

    critical_amenities = [
        element
        for element in amenities.get("elements", [])
        if element.get("tags", {}).get("amenity")
        in {"school", "hospital", "clinic", "fire_station", "police"}
    ]

    external_affected_areas = [
        area for area in ["Malaysia", "Singapore"] if re.search(rf"\b{area}\b", report_text)
    ]
    term_counts = count_terms(
        report_text,
        ["prolonged dry weather", "hotspot", "smoke haze", "prevailing winds"],
    )

    fire_smoke_transport = (
        term_counts["prolonged dry weather"] > 0
        and term_counts["hotspot"] > 0
        and term_counts["smoke haze"] > 0
        and term_counts["prevailing winds"] > 0
        and len(external_affected_areas) >= 2
    )
    competing_mechanisms = {
        "rainfall_flooding": bool(re.search(r"\bflood|flooding\b", report_text, re.IGNORECASE)),
        "volcanic_ashfall": bool(
            re.search(r"\bvolcanic\b|\bashfall\b|\bash fall\b", report_text, re.IGNORECASE)
        ),
        "heat_only": bool(re.search(r"\bheat[- ]?wave\b", report_text, re.IGNORECASE)),
    }

    mechanism_label = (
        "dry_weather_fire_smoke_haze_transport"
        if fire_smoke_transport and not any(competing_mechanisms.values())
        else "mixed_or_uncertain_haze_mechanism"
    )

    high_priority_conditions = {
        "fire_smoke_transport_chain": mechanism_label == "dry_weather_fire_smoke_haze_transport",
        "persistent_local_dryness": dry_run_days >= 5 and point_precip_total_mm <= 1.0,
        "cross_border_transport": len(external_affected_areas) >= 2,
        "substantial_exposure_context": exposed_population_rounded >= 500000
        and len(critical_amenities) >= 1,
        "imagery_context_consistent": term_counts["smoke haze"] >= 1,
    }
    response_priority = "high" if all(high_priority_conditions.values()) else "moderate"

    expected_response_json = {
        "mechanism_label": mechanism_label,
        "response_priority": response_priority,
        "key_findings": [
            f"{dry_run_days}-day zero-rainfall run in the local daily sequence",
            f"{point_precip_total_mm:.1f} mm sampled-period point rainfall",
            "smoke affected Malaysia and Singapore beyond Sumatra and Kalimantan",
            f"about {exposed_population_rounded:,} people in the exposure context",
        ],
        "impact_chain": (
            "Prolonged dry weather increased hotspot activity over Sumatra and Kalimantan; "
            "persistent fires produced moderate to dense smoke haze; prevailing winds carried "
            "haze toward Malaysia and Singapore, creating a cross-border public-health and "
            "service-continuity priority."
        ),
        "imagery_interpretation": (
            "Regional imagery and report captions are consistent with visible smoke-haze "
            "transport, but the annual change summary is contextual and should not be treated "
            "as direct PM2.5, mortality, or structural-damage evidence."
        ),
        "priority_rationale": (
            "High priority is warranted because the dry spell, very low point rainfall, "
            "cross-border transport, large exposure context, and critical-place context align "
            "with a smoke-haze response problem rather than a flood, ashfall, or heat-only event."
        ),
    }

    required_metrics = [
        {
            "name": "dry_run_days",
            "value": dry_run_days,
            "tolerance": 0,
            "expected_use": "supports persistent dry-weather preconditioning",
        },
        {
            "name": "point_precip_total_mm",
            "value": point_precip_total_mm,
            "tolerance": 0.1,
            "expected_use": "supports very low sampled-period rainfall",
        },
        {
            "name": "exposed_population_rounded",
            "value": exposed_population_rounded,
            "tolerance": 1000,
            "expected_use": "supports response-priority scale",
        },
        {
            "name": "alphaearth_change_mean",
            "value": alphaearth_change_mean,
            "tolerance": 0.001,
            "expected_use": "contextual imagery-change anchor, not a direct impact metric",
        },
    ]

    required_claims = [
        "Dry-weather fire-smoke haze transport is the dominant mechanism.",
        "The rainfall anchors indicate persistent local dryness rather than a rainfall-flood mechanism.",
        "Smoke haze was transported beyond source regions toward Malaysia and Singapore.",
        "High response priority is justified by persistence, cross-border transport, exposure scale, and critical-place context.",
        "Imagery is useful as smoke-haze context but not direct evidence of PM2.5 concentrations, deaths, hospitalizations, or structural damage.",
    ]

    forbidden_claims = [
        "Exact deaths, hospitalizations, PM2.5 concentrations, economic losses, or school closures.",
        "A claim that every location in the affected region had the same rainfall or wind conditions.",
        "Attribution to one ignition cause, land-management practice, or actor.",
        "Treating annual embedding change as direct evidence of smoke exposure, structural damage, or health impact.",
        "Reframing the event as rainfall flooding, volcanic ashfall, or heat-only without reconciling the smoke-haze chain.",
    ]

    computed_gt = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "subtype": "compound_impact_chain_response_priority_with_image_context",
        "primary_gt": expected_response_json,
        "answer_guidance": {
            "answer": {
                "mechanism_label": mechanism_label,
                "response_priority": response_priority,
            },
            "answer_type": "structured_hybrid_response",
            "canonical_stance": (
                "The 2019 Indonesian episode should be diagnosed as high-priority "
                "dry-weather fire-smoke haze transport, not flooding, volcanic ashfall, "
                "or a heat-only event."
            ),
            "canonical_answer": mechanism_label,
            "response_priority": response_priority,
            "structured_answer": expected_response_json,
            "required_claims": required_claims,
            "required_metrics": required_metrics,
            "forbidden_claims": forbidden_claims,
            "acceptable_variants": [
                "A respondent may call the mechanism transboundary fire-smoke haze transport if dry-weather preconditioning and wind transport are explicit.",
                "A response may use moderate-to-dense haze language instead of smoke-haze if the dry-fire and transport chain is preserved.",
                "The imagery discussion may mention satellite or regional visual context, provided it does not treat the imagery as a direct health-loss or damage measurement.",
            ],
        },
        "required_findings": [
            {
                "id": "mechanism",
                "finding": "dry-weather fire-smoke haze transport is the dominant mechanism",
            },
            {
                "id": "dryness",
                "finding": "local sampled weather indicates persistent low-rainfall conditions",
            },
            {
                "id": "transport",
                "finding": "smoke-haze transport affected Malaysia and Singapore",
            },
            {
                "id": "priority",
                "finding": "response priority should be high because hazard persistence, transport, exposure, and critical-place context align",
            },
            {
                "id": "imagery",
                "finding": "imagery is useful for smoke-haze context but not direct evidence of PM2.5, deaths, or infrastructure damage",
            },
        ],
        "numeric_tolerances": {
            "dry_run_days": {"value": dry_run_days, "tolerance": 0},
            "point_precip_total_mm": {"value": point_precip_total_mm, "tolerance": 0.1},
            "exposed_population_rounded": {
                "value": exposed_population_rounded,
                "tolerance": 1000,
            },
            "alphaearth_change_mean": {
                "value": alphaearth_change_mean,
                "tolerance": 0.001,
                "role": "contextual_not_priority_decisive",
            },
        },
        "reasoning_requirements": [
            "Connect dry conditions to increased hotspots rather than treating haze as a stand-alone atmospheric label.",
            "Explain the transport step from Sumatra/Kalimantan toward Malaysia and Singapore.",
            "Use exposure and critical-place context to justify response priority.",
            "Treat imagery as smoke-haze context, not as direct health-loss or damage measurement.",
        ],
        "forbidden_overclaims": [
            *forbidden_claims,
        ],
        "supporting_metrics": {
            "event_window": anchor["temporal_window"],
            "expected_response_json": expected_response_json,
            "priority_conditions": high_priority_conditions,
            "text_term_counts": term_counts,
            "external_affected_areas": external_affected_areas,
            "critical_amenities_count": len(critical_amenities),
            "intermediate_values": {
                "power_precip_mm_by_day": power_precip_by_day,
                "open_meteo_precip_sum_mm_by_day": dict(zip(daily["time"], daily["precipitation_sum"])),
                "open_meteo_wind_speed_10m_max_kmh_by_day": dict(
                    zip(daily["time"], daily["wind_speed_10m_max"])
                ),
                "peak_wind_kmh": peak_wind_kmh,
            },
            "competing_mechanisms_present_in_report_text": competing_mechanisms,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": list(source_paths.values()),
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Mechanism diagnosis",
                    "points": 4,
                    "description": "Identifies dry-weather fire-smoke haze transport as the dominant mechanism, using the canonical label or an equivalent phrase that includes both dry-weather fire or hotspot preconditioning and smoke-haze transport.",
                    "partial_credit": "Award partial credit for recognizing smoke haze but omitting either the dry-weather setup or the transport step; no credit for flooding, ashfall, or heat-only framing.",
                },
                {
                    "name": "Response priority",
                    "points": 3,
                    "description": "Assigns high response priority and ties it to hazard persistence, cross-border transport, exposure scale, and critical-place context as an emergency response problem.",
                    "partial_credit": "Award partial credit for returning moderate with otherwise sound reasoning, or for returning high with a thin rationale.",
                },
                {
                    "name": "Quantitative anchors",
                    "points": 4,
                    "description": "Uses the decisive quantitative anchors: the 7-day zero-rainfall run, 0.8 mm sampled-period rainfall, roughly 867,837 people, and the optional 0.0262 embedding-change context without overloading the answer with irrelevant numbers.",
                    "partial_credit": "Award partial credit for including at least two correct anchors but missing exposure scale or dryness persistence.",
                },
                {
                    "name": "Impact-chain reasoning",
                    "points": 4,
                    "description": "Builds a physically coherent chain from dry weather to hotspots, smoke haze, wind transport, and downwind exposure in Malaysia and Singapore, including public-health or service-continuity implications.",
                    "partial_credit": "Award partial credit for a generic haze impact chain that lacks source-region or transboundary detail.",
                },
                {
                    "name": "Imagery interpretation",
                    "points": 2,
                    "description": "Explains that imagery supports smoke-haze context but does not directly measure health outcomes, PM2.5, or structural damage.",
                    "partial_credit": "Award partial credit for mentioning imagery but leaving its evidentiary role ambiguous.",
                },
                {
                    "name": "Distractor and overclaim control",
                    "points": 2,
                    "description": "Rejects rainfall flooding, volcanic ashfall, and heat-only explanations while avoiding unsupported loss, pollution, ignition, or uniform-condition claims.",
                    "partial_credit": "Award partial credit for avoiding most overclaims but not clearly rejecting all distractors.",
                },
                {
                    "name": "Output format",
                    "points": 1,
                    "description": "Returns valid JSON with exactly the requested keys and 3-5 concise key findings.",
                    "partial_credit": "Award partial credit for a minor formatting issue that does not obscure the answer.",
                },
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
